          "gu": "૧ કિલો ચીકનને પાણીથી બરાબર ધોઈ લો. કડાઈમાં તેલ અથવા ઘી ગરમ કરી ઝીણી સમારેલી ડુંગળી ગુલાબી થાય ત્યાં સુધી સાંતળો. તેમાં આદું, લસણ અને મરચાંની પેસ્ટ ઉમેરી ૨ મિનિટ સાંતળો. ટમેટાની પ્યુરી અને દહીં ઉમેરી તેલ છૂટું પડે ત્યાં સુધી પકાવો. ચીકનના ટુકડા, સ્વાદ અનુસાર મીઠું અને ૫૦ ગ્રામ રીચ એન સ્પાઈસી સ્પે. ચીકન મસાલો ઉમેરી ૫ મિનિટ સાંતળો. ૧ થી ૨ ગ્લાસ પાણી ઉમેરી ઢાંકીને ચીકન બરાબર ચડી જાય અને ઘટ્ટ ગ્રેવી થાય ત્યાં સુધી ધીમી આંચે પકાવો. કોથમીરથી સજાવી રોટલી, નાન અથવા ભાત સાથે ગરમા ગરમ સર્વ કરો."
