          "gu": "તેલ અથવા ઘીમાં મીઠું, દળેલો કાંદો, આદુ મરચાં લસણ પેસ્ટ નાંખી ૨ થી ૩ મિનિટ ફ્રાય કરો ત્યાર બાદ મટન અથવા ચીકન નાંખી ૨ મિનિટ ફ્રાય કરો. અડધો ગ્લાસ પાણી નાંખી મીડીયમ આંચ પર ગોશ્ત ગળે ત્યાં સુધી પાકવા દો. દહીંમાં વ્હાઈટ ચીકન/મટન મસાલો નાખી મિક્સ કરી મટન/ચીકનના મિશ્રણમાં મિક્સ કરી હલકી આંચ પર તેલ ઉપર આવે ત્યાં સુધી પાકવા દઈ ઉપરથી ફુદીનો નાંખી સજાવી નાન પરાઠા સાથે સર્વ કરો."
