          "gu": "બોનલેસ મટનને ધોઈ નિતારી લો. તેમાં આદું, મરચાં, લસણની પેસ્ટ ઉમેરી ૩૦ મિનિટ મેરીનેટ કરો. મટન નરમ થાય ત્યાં સુધી ધીમી આંચે પકાવો. ઠંડુ થયા પછી રીચ એન સ્પાઈસી ભુના ગૌસ્ત ઇન્સ્ટન્ટ મિક્સ ઉમેરી ગ્રાઇન્ડરમાં અધકચરું પીસી લો. ઘી અથવા તેલમાં ડુંગળી ગુલાબી થાય ત્યાં સુધી સાંતળો. તેમાં મટનનું મિશ્રણ ઉમેરી સાંતળો, છેલ્લે લીંબુનો રસ ઉમેરી ૫ મિનિટ ફ્રાય કરો. કોથમીરથી સજાવી ગરમ નાન કે પરાઠા સાથે પીરસો."
